// CreateTableWithDBType creates the G_L_Account table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *GLAccount) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GLAccountTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetGLAccountPostgresTableSchema()
	} else {
		schema = GetGLAccountTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create G_L_Account table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *GLAccount) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, GLAccountTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$G_L_Account$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (search_name)`,
		fmt.Sprintf("%s$G_L_Account$search_name", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index search_name: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (reconciliation_account)`,
		fmt.Sprintf("%s$G_L_Account$reconciliation_account", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index reconciliation_account: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gen_bus_posting_group)`,
		fmt.Sprintf("%s$G_L_Account$gen_bus_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gen_bus_posting_group: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (gen_prod_posting_group)`,
		fmt.Sprintf("%s$G_L_Account$gen_prod_posting_group", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index gen_prod_posting_group: %w", err)
	}
	var keys []sift.Key
	for _, spec := range gLAccountSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, GLAccountTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, GLAccountTableName, keys)
}

// gLAccountSIFTSpecs are the table's keys with sum_index_fields
func gLAccountSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *GLAccount) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, GLAccountTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range gLAccountSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, GLAccountTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: GLAccountTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, GLAccountTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

