	t.Tax_prod_posting_group = types.NewCode(tax_prod_posting_groupNull.String)
	t.Exchange_rate_adjustment = GLAccountExchange_rate_adjustment(exchange_rate_adjustmentInt)

	// Store old values for field tracking
